// Checks the session can be asked about, then builds the Slack texts and wait limits.
const input = $('When Called By Another Workflow').first().json;
const cfg = $('Load Config').first().json;
const row = $('Get Session Row').first().json ?? {};
const mode = input.mode || 'auto';

let blockStatus = null;
if (!row.id) blockStatus = 'skipped_no_row';
else if (row.booking_status !== 'active') blockStatus = 'skipped_not_active';
// Host list from PF Config: the test host (mock) or the pilot hosts (production). Empty = all hosts.
else if (cfg.hostAllowList.length && !cfg.hostAllowList.includes((row.host_email || '').toLowerCase())) blockStatus = 'guard_blocked';

const tz = cfg.timezone;
const start = DateTime.fromISO(row.starts_at || $now.toISO()).setZone(tz);
const end = DateTime.fromISO(row.ends_at || $now.toISO()).setZone(tz);
// Wait for the first answer until the session ends, but at least 2 minutes.
const minAsk = $now.plus({ minutes: 2 });
const askUntil = (end > minAsk ? end : minAsk).toUTC().toISO();

const tag = cfg.mockMode ? '[MOCK] ' : '';
const hostFirst = (row.host_name || '').split(' ')[0] || 'there';
const who = row.participant_name || row.participant_email || 'the participant';
const first = row.participant_first_name || who;
const when = start.toFormat('HH:mm');

const out = {
    ok: blockStatus === null,
    block_status: blockStatus,
    mode,
    invitee_uri: row.invitee_uri ?? input.invitee_uri,
    host_email: row.host_email,
    ends_at: row.ends_at,
    ask_until: askUntil,
    reminder_minutes: cfg.finalTimeoutMinutes,
    ask_text: `${tag}Hi ${hostFirst}, your session "${row.event_name}" with ${who} started at ${when} (${tz}). Did ${first} join?`,
    remind_text: `${tag}Reminder: did ${who} join your session "${row.event_name}" at ${when} (${tz})?`,
    yes_note_before_end: `:white_check_mark: You answered: *${first} joined*. When the session ends at ${end.toFormat('HH:mm')}, I will ask you about the reward.`,
    yes_note_after_end: `:white_check_mark: You answered: *${first} joined*. I will ask you about the reward now.`,
    no_note: `:x: You answered: *${first} did not join*.`,
    rebook_text: `${tag}Do you want me to send ${first} an email with a link to book a new time? It comes from noreply@info.n8n.io.`,
    rebook_yes_note: `:email: OK, I will send ${first} the link to book a new time.`,
    rebook_no_note: `:no_entry_sign: OK, I will not send anything to ${first}.`,
    rebook_timeout_note: `:zzz: No answer, so I did not send anything to ${first}.`,
    first_timeout_note: ':hourglass_flowing_sand: No answer yet. I sent you a reminder.',
    final_timeout_note: ':zzz: No answer, so I stopped asking. You can still tell Darwin later: "I want to send the reward for my last session".',
};

// Slack question messages. One helper for both layouts (PF Config slackButtons):
//   off: links in the text (a click opens the browser for a moment and comes back to Slack)
//   on:  native buttons; PF Button Router resumes this run from the button value.
// The resume address is the same for every Wait node in this run; the suffix selects the Wait node.
const [resumeBase, resumeQuery] = String($execution.resumeUrl).split('?');
const answerUrl = (suffix, answer) => `${resumeBase}/${suffix}?${resumeQuery}&answer=${answer}`;
function question(text, suffix, options) {
  if (cfg.slackButtons) {
    return {
      text,
      blocks: [
        { type: 'section', text: { type: 'mrkdwn', text } },
        { type: 'actions', elements: options.map((o) => ({
          type: 'button',
          action_id: `pf_answer_${suffix}_${o.answer}`,
          text: { type: 'plain_text', text: o.label },
          value: answerUrl(suffix, o.answer),
          ...(o.style ? { style: o.style } : {}),
        })) },
      ],
    };
  }
  const links = options.map((o) => `<${answerUrl(suffix, o.answer)}|${o.label}>`).join('     ·     ');
  const full = `${text}\n\n${links}`;
  return { text: full, blocks: [{ type: 'section', text: { type: 'mrkdwn', text: full } }] };
}
const joinedOptions = [
  { label: 'Yes, they joined', answer: 'yes', style: 'primary' },
  { label: 'No, they did not', answer: 'no' },
];

return [{
  json: {
    ...out,
    msg_first: question(out.ask_text, 'first', joinedOptions),
    msg_reminder: question(out.remind_text, 'reminder', joinedOptions),
    msg_rebook: question(out.rebook_text, 'rebook', [
      { label: 'Yes, send it', answer: 'yes', style: 'primary' },
      { label: 'No, do not send it', answer: 'no' },
    ]),
  },
}];

// Builds the rebook email and applies the guard.
const cfg = $('Load Config').first().json;
const row = $('Get Session Row').first().json;
const tz = cfg.timezone;
const first = row.participant_first_name || 'there';
const to = (row.participant_email || '').toLowerCase();
const link = row.booking_link;

// Why the email cannot be sent. The last check exists only in mock mode.
let blockedNote = null;
if (!to) blockedNote = `:warning: I could not send the email: ${first} has no email address in the booking.`;
else if (!link) blockedNote = ':warning: I could not send the email: there is no booking link for this session.';
else if (cfg.mockMode && !new RegExp(cfg.allowedParticipantEmailPattern).test(to)) blockedNote = `:lock: Test mode: I only send emails to Aniol's test addresses, so nothing was sent to ${to}.`;

const tag = cfg.mockMode ? '[MOCK] ' : '';
// Text by Aniol (DWN-6, 2026-10-27).
const text = [
  'Hi,',
  '',
  'We are sorry you could not attend today’s research session with the n8n team.',
  '',
  'We are very interested in hearing from you and learning from your experience so we can build a better product.',
  '',
  `If you would like to reschedule, you can do it using the following link: ${link}`,
  '',
  'Best,',
  'n8n Research team',
].join('\n');

return [{
  json: {
    allowed: blockedNote === null,
    to,
    from: cfg.emailFrom,
    reply_to: cfg.emailReplyTo,
    subject: `${tag}About your n8n research session`,
    text,
    sent_note: `:email: Sent to ${first} (${to}) at ${$now.setZone(tz).toFormat('HH:mm')}.`,
    blocked_note: blockedNote,
  },
}];
